# Emoji POS Printer Station Installer (Windows)
# Installs the localhost ESC/POS bridge for a USB EPSON TM-T70II.
$ErrorActionPreference = 'Stop'
$payload = @'

'@
if (-not (Get-Command node.exe -ErrorAction SilentlyContinue)) {
  Write-Host 'Node.js 22 LTS is required. Install it from https://nodejs.org/, then run this installer again.' -ForegroundColor Yellow
  Start-Process 'https://nodejs.org/'
  Read-Host 'Press Enter to close'
  exit 1
}
$major = [int]((node --version).TrimStart('v').Split('.')[0])
if ($major -lt 22) { throw 'Node.js 22 LTS or later is required.' }
$root = Join-Path $env:LOCALAPPDATA 'EmojiPOSPrinterStation'
New-Item -ItemType Directory -Force -Path $root | Out-Null
$zip = Join-Path $env:TEMP 'emoji-pos-printer-station.zip'
[IO.File]::WriteAllBytes($zip, [Convert]::FromBase64String(($payload -replace '\s','')))
Expand-Archive -LiteralPath $zip -DestinationPath $root -Force
Remove-Item $zip -Force
$printer = Read-Host 'Enter the exact Windows printer name for the EPSON TM-T70II'
if ([string]::IsNullOrWhiteSpace($printer)) { throw 'A Windows printer name is required.' }
$token = -join ((48..57)+(65..90)+(97..122) | Get-Random -Count 48 | ForEach-Object { [char]$_ })
$config = @{ host='127.0.0.1'; port=17890; token=$token; allowedOrigins=@('https://pos.emoji.tw','https://www.emoji.tw'); printers=@{ 'receipt-main'=@{ name='EPSON TM-T70II'; queue=$printer } } }
$config | ConvertTo-Json -Depth 5 | Set-Content -Encoding UTF8 (Join-Path $root 'config.json')
$node=(Get-Command node.exe).Source
$start = Join-Path $root 'start-bridge.cmd'
@"
@echo off
cd /d "$root"
"$node" service.js
"@ | Set-Content -Encoding ASCII $start
$startup = [Environment]::GetFolderPath('Startup')
$shell = New-Object -ComObject WScript.Shell
$link = $shell.CreateShortcut((Join-Path $startup 'Emoji POS Printer Station.lnk'))
$link.TargetPath = $start; $link.WorkingDirectory = $root; $link.WindowStyle = 7; $link.Save()
Start-Process -FilePath $start -WindowStyle Minimized
Write-Host ''
Write-Host 'Emoji POS Printer Station installed and started.' -ForegroundColor Green
Write-Host 'In POS > 設定 > 列印站設定, enter:'
Write-Host '  URL: http://127.0.0.1:17890'
Write-Host '  Printer ID: receipt-main'
Write-Host "  Pairing token: $token" -ForegroundColor Cyan
Write-Host 'Keep this token private. It is stored only on this PC.'
Read-Host 'Press Enter to close'
